  (12125, 6412, '冠军奖券', '', '幻想开心辞典冠军奖券，可在龙城王小丫处领取奖励'),
  (12126, 6413, '亚军奖券', '', '幻想开心辞典亚军奖券，可在龙城王小丫处领取奖励'),
